INSERT INTO public.biblioteca_platillos (id,nombre,categoria,texto,foto_url,smae_equivalentes,tags_restriccion,keywords,calorias,proteina,carbohidratos,grasas) VALUES
('smae_dish_huevos_jamon_pan','Huevos revueltos con jamón de pavo y pan integral tostado','desayuno','Preparar 2 huevos enteros (100 g) revueltos con 2 rebanadas de jamón de pavo bajo en sodio (42 g) en sartén con 1 cdita de aceite de oliva (5 ml). Acompañar con 2 rebanadas de pan integral tostado (54 g).','https://images.unsplash.com/photo-1525351484163-7529414344d8?w=600&auto=format&fit=crop&q=80','{"aoa_m":2,"aoa_b":1,"cereales_sg":2,"grasas_sp":1}'::jsonb,ARRAY['gluten','animal_meat']::text[],ARRAY['huevo','huevos','jamon','pavo','pan','tostado','desayuno']::text[],390,25,30,18),
('smae_dish_omelette_claras_panela','Omelette de claras con espinacas, queso panela y tortilla de maíz','desayuno','Batir 4 claras de huevo (132 g) y cocinar en sartén con 1 cdita de aceite de oliva (5 ml). Rellenar con 2 tazas de espinacas salteadas (120 g) y 40 g de queso panela en cubos. Acompañar con 1 tortilla de maíz caliente (30 g).','https://images.unsplash.com/photo-1510693206972-df098062cb71?w=600&auto=format&fit=crop&q=80','{"aoa_mb":2,"aoa_b":1,"verduras":1,"cereales_sg":1,"grasas_sp":1}'::jsonb,ARRAY['lacteos']::text[],ARRAY['omelette','claras','espinacas','panela','queso','tortilla']::text[],275,25,19,10),
('smae_dish_avena_whey_frutos','Bowl de avena con proteína Whey, frutos rojos y almendras','desayuno','Cocer ⅔ de taza de avena en hojuelas (40 g) en 1 taza de leche descremada (240 ml) con canela al gusto. Integrar 20 g de proteína Whey en polvo y coronar con 1 taza de fresas o frutos rojos (150 g) y 10 almendras fileteadas (12 g).','https://images.unsplash.com/photo-1584776296944-ab6fb57b0bdd?w=600&auto=format&fit=crop&q=80','{"cereales_sg":2,"leche_d":1,"aoa_mb":2,"frutas":1,"grasas_cp":1}'::jsonb,ARRAY['lacteos','nueces']::text[],ARRAY['avena','proteina','whey','frutos rojos','fresas','almendras','leche']::text[],445,30,60,9),
('smae_dish_hotcakes_avena_platano','Hot cakes de avena con claras, plátano y miel de abeja','desayuno','Licuar ⅔ de taza de avena en hojuelas (40 g) con ½ plátano (54 g), 4 claras de huevo (132 g), canela y vainilla. Cocinar en sartén antiadherente y servir con 2 cditas de miel de abeja (10 g) y 2 cditas de crema de cacahuate natural (10 g).','https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=600&auto=format&fit=crop&q=80','{"cereales_sg":2,"frutas":1,"aoa_mb":2,"azucares_sg":1,"grasas_cp":1}'::jsonb,ARRAY['nueces']::text[],ARRAY['hot cakes','hotcakes','pancakes','avena','platano','miel','claras']::text[],390,21,58,7),
('smae_dish_chilaquiles_pollo_panela','Chilaquiles horneados con pollo deshebrado y queso panela','desayuno','Hornear 3 tortillas de maíz (90 g) en triángulos hasta dorar. Bañar con salsa verde hervida (100 g de tomate verde, cebolla y cilantro) y servir con 90 g de pechuga de pollo deshebrada, 40 g de queso panela desmoronado y ⅓ de aguacate Hass (33 g).','https://images.unsplash.com/photo-1628294895950-9805252327bc?w=600&auto=format&fit=crop&q=80','{"cereales_sg":3,"aoa_mb":3,"aoa_b":1,"verduras":1,"grasas_sp":1}'::jsonb,ARRAY['lacteos','animal_meat']::text[],ARRAY['chilaquiles','totopos','pollo','panela','salsa verde','desayuno']::text[],455,36,49,11),
('smae_dish_avocado_toast_huevo','Avocado toast en pan de masa madre con huevos estrellados','desayuno','Tostar 2 rebanadas de pan de masa madre (60 g). Untar ⅔ de pieza de aguacate Hass machacado (66 g) con limón, sal y pimienta. Montar 2 huevos estrellados al comal sin aceite (100 g) y acompañar con ½ taza de jitomate cherry (60 g).','https://images.unsplash.com/photo-1525351484163-7529414344d8?w=600&auto=format&fit=crop&q=80','{"cereales_sg":2,"aoa_m":2,"grasas_sp":2,"verduras":0.5}'::jsonb,ARRAY['gluten']::text[],ARRAY['avocado','toast','aguacate','pan','masa madre','huevo','estrellado']::text[],393,19,32,20),
('smae_dish_pollo_arroz_brocoli','Pechuga de pollo a la plancha con arroz al vapor y brócoli','comida','Asar 150 g de pechuga de pollo en sartén con 1 cdita de aceite de oliva (5 ml), ajo, sal y limón. Acompañar con 1 taza de arroz blanco o integral cocido (140 g) y 1 taza de arbolitos de brócoli al vapor (184 g).','https://images.unsplash.com/photo-1546069901-ba9599a7e63c?w=600&auto=format&fit=crop&q=80','{"aoa_mb":5,"cereales_sg":2,"verduras":2,"grasas_sp":1}'::jsonb,ARRAY['animal_meat']::text[],ARRAY['pollo','pechuga','arroz','brocoli','comida']::text[],435,43,38,10),
('smae_dish_bistec_papa_ensalada','Bistec de res magro con papa al horno, frijoles y ensalada','comida','Asar 120 g de bistec de res magro sazonado con sal y pimienta. Servir con 1 papa mediana al horno en gajos (136 g), ½ taza de frijoles negros de la olla (86 g), ensalada fresca de lechuga con jitomate y ⅓ de pieza de aguacate Hass (33 g).','https://images.unsplash.com/photo-1603048588665-791ca8aea617?w=600&auto=format&fit=crop&q=80','{"aoa_b":4,"cereales_sg":2,"leguminosas":1,"verduras":1,"grasas_sp":1}'::jsonb,ARRAY['animal_meat','carne_roja']::text[],ARRAY['bistec','res','carne','papa','frijoles','ensalada','aguacate']::text[],550,42,54,18),
('smae_dish_salmon_quinoa_esparragos','Salmón al grill con quinoa, espárragos y aceite de oliva','comida','Sellar 120 g de filete de salmón fresco a la plancha con limón, eneldo y pimienta. Acompañar con 1 taza de quinoa cocida (120 g) y 9 espárragos salteados (135 g) con 2 cditas de aceite de oliva extra virgen (10 ml).','https://images.unsplash.com/photo-1467003909585-2f8a72700288?w=600&auto=format&fit=crop&q=80','{"aoa_b":4,"cereales_sg":2,"verduras":1.5,"grasas_sp":2}'::jsonb,ARRAY['animal_meat','mariscos']::text[],ARRAY['salmon','pescado','quinoa','esparragos','comida']::text[],488,35,36,22),
('smae_dish_pescado_veracruzana_arroz','Filete de pescado blanco a la veracruzana con arroz y aguacate','comida','Cocinar 160 g de filete de pescado blanco en salsa de jitomate, cebolla y pimiento morrón (150 g) guisada con 1 cdita de aceite de oliva. Servir con 1 taza de arroz blanco al vapor (140 g) y rodajas de aguacate.','https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?w=600&auto=format&fit=crop&q=80','{"aoa_mb":4,"cereales_sg":2,"verduras":1.5,"grasas_sp":1.5}'::jsonb,ARRAY['animal_meat','mariscos']::text[],ARRAY['pescado','tilapia','huachinango','veracruzana','arroz','aguacate']::text[],405,35,36,12),
('smae_dish_tacos_pollo_aguacate','Tacos de pechuga de pollo con pico de gallo y aguacate','comida','Calentar 3 tortillas de maíz (90 g) y rellenar con 120 g de pechuga de pollo deshebrada o asada. Acompañar con 1 taza de pico de gallo fresco (jitomate, cebolla, cilantro y limón) y ½ pieza de aguacate Hass en rebanadas (50 g).','https://images.unsplash.com/photo-1551504734-5ee1c4a1479b?w=600&auto=format&fit=crop&q=80','{"cereales_sg":3,"aoa_mb":4,"verduras":1,"grasas_sp":1.5}'::jsonb,ARRAY['animal_meat']::text[],ARRAY['tacos','pollo','tortilla','maiz','pico de gallo','aguacate']::text[],463,36,49,12),
('smae_dish_picadillo_res_arroz','Picadillo de res magro con verduras y arroz blanco','comida','Guisar 120 g de carne molida de res magra (90/10) con ½ taza de zanahoria picada y 1 calabacita en cubos en caldillo de jitomate natural con 1 cdita de aceite de oliva. Servir acompañado de 1 taza de arroz blanco cocido (140 g).','https://images.unsplash.com/photo-1603048588665-791ca8aea617?w=600&auto=format&fit=crop&q=80','{"aoa_b":4,"cereales_sg":2,"verduras":2,"grasas_sp":1}'::jsonb,ARRAY['animal_meat','carne_roja']::text[],ARRAY['picadillo','res','molida','zanahoria','calabacita','arroz']::text[],455,36,38,17),
('smae_dish_ensalada_pollo_aguacate','Ensalada fresca con pechuga de pollo al grill, aguacate y tostadas','cena','Mezclar 3 tazas de lechuga romana con 1 taza de pepino y jitomate. Montar 120 g de pechuga de pollo a la plancha en tiras, ⅓ de pieza de aguacate Hass (33 g) y aderezar con 1 cdita de aceite de oliva y limón. Acompañar con 1 paquete de tostadas horneadas Salmas (3 pzas).','https://images.unsplash.com/photo-1540420773420-3366772f4999?w=600&auto=format&fit=crop&q=80','{"aoa_mb":4,"verduras":2,"grasas_sp":2,"cereales_sg":1}'::jsonb,ARRAY['animal_meat']::text[],ARRAY['ensalada','pollo','lechuga','pepino','aguacate','salmas','tostadas','cena']::text[],370,34,23,14),
('smae_dish_quesadillas_oaxaca_champinones','Quesadillas en tortilla de maíz con queso Oaxaca light y champiñones','cena','Saltear 1 taza de champiñones rebanados (96 g) con ajo y epazote. Armar 2 quesadillas en tortilla de maíz (60 g) con 60 g de queso Oaxaca light deshebrado y los champiñones. Acompañar con ⅓ de aguacate Hass (33 g) y salsa casera.','https://images.unsplash.com/photo-1628294895950-9805252327bc?w=600&auto=format&fit=crop&q=80','{"cereales_sg":2,"aoa_b":2,"verduras":1,"grasas_sp":1}'::jsonb,ARRAY['lacteos']::text[],ARRAY['quesadillas','queso','oaxaca','champinones','tortilla','cena']::text[],320,20,34,11),
('smae_dish_sandwich_pavo_panela','Sándwich integral de pechuga de pavo, queso panela y aguacate','cena','Armar un sándwich con 2 rebanadas de pan integral de caja (54 g), 2 rebanadas de pechuga de pavo (42 g), 40 g de queso panela, lechuga, jitomate, mostaza Dijon y ⅓ de pieza de aguacate Hass (33 g).','https://images.unsplash.com/photo-1528735602780-2552fd46c7af?w=600&auto=format&fit=crop&q=80','{"cereales_sg":2,"aoa_mb":1,"aoa_b":1,"verduras":0.5,"grasas_sp":1}'::jsonb,ARRAY['lacteos','gluten','animal_meat']::text[],ARRAY['sandwich','pavo','panela','pan integral','aguacate','cena']::text[],293,19,32,9),
('smae_dish_tostadas_atun_aguacate','Tostadas horneadas de atún con pico de gallo y aguacate','cena','Mezclar 90 g de atún en agua drenado con 1 taza de pepino, jitomate, cebolla morada, cilantro y jugo de limón. Servir sobre 4 tostadas de maíz horneadas y coronar con ⅓ de pieza de aguacate Hass (33 g).','https://images.unsplash.com/photo-1540420773420-3366772f4999?w=600&auto=format&fit=crop&q=80','{"aoa_mb":3,"cereales_sg":2,"verduras":1,"grasas_sp":1}'::jsonb,ARRAY['animal_meat','mariscos']::text[],ARRAY['atun','tostadas','salmas','pico de gallo','aguacate','cena']::text[],330,27,34,8),
('smae_dish_yogurt_griego_frutos_almendras','Yogurt griego sin azúcar con fresas y almendras','colacion','Servir ¾ de taza de yogurt griego natural sin azúcar (150 g) acompañado de 1 taza de fresas rebanadas (166 g) y 10 piezas de almendras fileteadas (12 g).','https://images.unsplash.com/photo-1488477181946-6428a0291777?w=600&auto=format&fit=crop&q=80','{"leche_d":1,"frutas":1,"grasas_cp":1}'::jsonb,ARRAY['lacteos','nueces']::text[],ARRAY['yogurt','yogur','griego','fresas','almendras','colacion','snack']::text[],225,12,30,7),
('smae_dish_manzana_crema_cacahuate','Manzana en gajos con crema de cacahuate natural','colacion','Cortar 1 manzana mediana (138 g) en gajos, espolvorear con canela al gusto y acompañar con 4 cucharaditas (20 g) de crema de cacahuate 100% natural sin azúcar.','https://images.unsplash.com/photo-1490474418585-ba9bad8fd0ea?w=600&auto=format&fit=crop&q=80','{"frutas":1,"grasas_cp":2}'::jsonb,ARRAY['nueces']::text[],ARRAY['manzana','cacahuate','crema de cacahuate','colacion','snack']::text[],200,6,21,10),
('smae_dish_shake_whey_platano','Batido post-entreno de proteína Whey con plátano y leche','colacion','Licuar 1 scoop de proteína Whey aislada (30 g) con ½ plátano tabasco (54 g), 1 taza de leche descremada (240 ml), hielo y canela al gusto.','https://images.unsplash.com/photo-1553530666-ba11a7da3888?w=600&auto=format&fit=crop&q=80','{"aoa_mb":3,"frutas":1,"leche_d":1}'::jsonb,ARRAY['lacteos']::text[],ARRAY['batido','licuado','smoothie','whey','proteina','platano','colacion']::text[],275,30,27,5),
('smae_dish_cottage_papaya_nueces','Bowl de queso cottage con papaya picada y nueces','colacion','Servir 6 cucharadas de queso cottage bajo en grasa (96 g) acompañado de 1 taza de papaya picada (140 g) y 7 mitades de nuez pecana (14 g).','https://images.unsplash.com/photo-1490474418585-ba9bad8fd0ea?w=600&auto=format&fit=crop&q=80','{"aoa_mb":2,"frutas":1,"grasas_cp":1}'::jsonb,ARRAY['lacteos','nueces']::text[],ARRAY['cottage','queso','papaya','nueces','fruta','colacion']::text[],210,17,18,7)
